// ---- content/pigeon.js ----
// Тема «Принцип Дирихле» (7+ класс + олимпиадный уровень).
// Формулировки, наихудший случай, остатки и делимость, геометрия, раскраски и знакомства, олимпиадные приёмы.
(function () {
  function fr(a, b) { return '<span class="fr"><span>' + a + '</span><span>' + b + '</span></span>'; }
  function sq(x) { return '<span class="sq">√<span>' + x + '</span></span>'; }
  var F = MM.fig;

  // квадрат 3 × 3, разбитый на 9 клеток; в одной клетке две точки
  var gp = {}, gd = [];
  for (var i = 0; i <= 3; i++) { gp['v' + i] = [i, 0]; gp['w' + i] = [i, 3]; gp['h' + i] = [0, i]; gp['k' + i] = [3, i]; if (i > 0 && i < 3) gd.push(['v' + i, 'w' + i], ['h' + i, 'k' + i]); }
  var pts10 = [[0.3, 0.4], [1.6, 0.5], [2.5, 0.3], [0.5, 1.6], [1.25, 1.3], [1.8, 1.75], [2.6, 1.4], [0.7, 2.5], [1.5, 2.6], [2.4, 2.4]];
  pts10.forEach(function (p, j) { gp['p' + j] = p; });
  var hideG = []; for (var j = 0; j <= 3; j++) hideG.push('v' + j, 'w' + j, 'h' + j, 'k' + j);
  var nol = pts10.map(function (_, j) { return 'p' + j; });
  var figSq = F({
    pts: gp, poly: [['v0', 'v3', 'k3', 'h3']], dash: gd, gold: [['p4', 'p5']], hide: hideG, nolab: nol, w: 220,
    alt: 'Квадрат 3 на 3 разбит на 9 единичных клеток, в нём 10 точек. В одной клетке оказались две точки, расстояние между ними не больше диагонали клетки'
  });

  MM.addTopic({
    id: 'pigeon',
    sec: 'comb',
    title: 'Принцип Дирихле',
    blurb: `Если кроликов больше, чем клеток, в какой-то клетке их хотя бы два. Простая мысль, но вся сила — в выборе клеток: остатки, части фигуры, пары чисел, цвета. Принцип Дирихле есть почти в каждом олимпиадном варианте.`,

    lessons: [
      { id: 'pg-l1', title: 'Принцип Дирихле', mins: 12, html: `
<div class="box"><div class="box-h">Принцип Дирихле</div>
<p>Если n + 1 кролик сидит в n клетках, то в какой-то клетке сидят хотя бы два кролика.</p></div>
<p>Доказательство: если бы в каждой клетке было не больше одного кролика, кроликов было бы не больше n.</p>
<h3>Общая форма</h3>
<div class="box"><div class="box-h">Если кроликов N, а клеток n</div>
<p>то в какой-то клетке не меньше <span class="m">${fr('N', 'n')}</span> кроликов, то есть не меньше N : n, округлённого вверх. Например, если кроликов больше kn, то в какой-то клетке хотя бы k + 1.</p></div>
<ul>
<li>Из 13 человек хотя бы двое родились в одном месяце.</li>
<li>Из 100 человек хотя бы 9 родились в одном месяце: 100 : 12 ≈ 8,3, округляем вверх.</li>
<li>В лесу 800 000 ёлок, на каждой не больше 500 000 иголок. Тогда найдутся две ёлки с одинаковым числом иголок: возможных чисел иголок 500 001 (от 0 до 500 000), а ёлок больше.</li>
</ul>
<h3>Форма «через среднее»</h3>
<p>Если сумма n чисел равна S, то хотя бы одно из них не меньше <span class="m">${fr('S', 'n')}</span> и хотя бы одно не больше <span class="m">${fr('S', 'n')}</span>. Это тот же принцип Дирихле: S единиц разложены по n «клеткам».</p>
<h3>Главное — выбрать клетки</h3>
<p>Сам принцип очевиден. Трудность в другом: понять, что в задаче кролики, а что клетки. Клетками бывают месяцы, остатки от деления, части фигуры, пары чисел, цвета. Клеток должно быть меньше, чем кроликов.</p>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Если в задаче нужно доказать, что «найдутся два одинаковых» или «найдутся два близких», почти наверняка это принцип Дирихле. Спроси себя: на какие группы разбить объекты, чтобы два объекта в одной группе давали ответ?</p></div>` },

      { id: 'pg-l2', title: 'Наихудший случай', mins: 12, html: `
<p>Задачи вида «сколько нужно взять, чтобы <b>наверняка</b>…» решаются в два шага.</p>
<div class="box"><div class="box-h">Два шага</div><ol>
<li><b>Пример.</b> Найти наибольшее количество объектов, при котором нужного свойства ещё может не быть, — «самый неудачный случай».</li>
<li><b>Оценка.</b> Доказать (обычно принципом Дирихле), что при одном объекте больше свойство обязательно появится.</li>
</ol><p>Ответ = (наибольшее число без свойства) + 1. Без примера решение неполное: вдруг хватает и меньшего числа?</p></div>
<div class="ex"><div class="ex-h">Пример: носки трёх цветов</div>
<p>В ящике 10 белых, 10 чёрных и 10 серых носков. Сколько нужно взять не глядя, чтобы наверняка…</p>
<ul>
<li><b>…были два одного цвета?</b> Три носка разных цветов — неудача, а из четырёх носков трёх цветов два одного цвета обязательно. Ответ: 4.</li>
<li><b>…были два белых?</b> Самый неудачный случай — все 20 небелых и один белый. Ответ: 22.</li>
<li><b>…были носки всех трёх цветов?</b> Можно вытащить все 20 носков двух цветов. Ответ: 21.</li>
</ul></div>
<div class="ex"><div class="ex-h">Пример: гарантированное количество</div>
<p>В классе 30 учеников. Сколько учеников, родившихся в одном месяце, найдётся наверняка? По принципу Дирихле — не меньше 30 : 12, округлённого вверх, то есть 3. А больше гарантировать нельзя: в шести месяцах может родиться по 3 человека, в шести — по 2.</p></div>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Представь, что объекты выдаёт злой противник, который старается как можно дольше не дать тебе нужное. Его лучшая стратегия и есть самый неудачный случай.</p></div>` },

      { id: 'pg-l3', title: 'Остатки и делимость', mins: 14, html: `
<h3>Остатки — клетки</h3>
<p>При делении на n бывает ровно n остатков: 0, 1, …, n − 1. Поэтому среди любых n + 1 целых чисел найдутся два с одинаковым остатком, и их разность делится на n.</p>
<h3>Суммы подряд</h3>
<div class="box"><div class="box-h">Лемма о суммах</div>
<p>Среди любых n целых чисел <span class="m">a<sub>1</sub>, …, a<sub>n</sub></span> можно выбрать несколько подряд идущих, сумма которых делится на n.</p></div>
<p>Доказательство: рассмотрим суммы <span class="m">S<sub>1</sub> = a<sub>1</sub></span>, <span class="m">S<sub>2</sub> = a<sub>1</sub> + a<sub>2</sub></span>, …, <span class="m">S<sub>n</sub></span>. Если какая-то делится на n — готово. Иначе n сумм дают только n − 1 ненулевых остатков, и две суммы <span class="m">S<sub>i</sub></span>, <span class="m">S<sub>j</sub></span> (i < j) имеют одинаковый остаток. Тогда <span class="m">S<sub>j</sub> − S<sub>i</sub> = a<sub>i+1</sub> + … + a<sub>j</sub></span> делится на n.</p>
<div class="ex"><div class="ex-h">Пример</div>
<p>Числа 2, 4, 1, 5, 7 и n = 5. Суммы: 2, 6, 7, 12, 19; остатки 2, 1, 2, 2, 4. У <span class="m">S<sub>1</sub></span> и <span class="m">S<sub>3</sub></span> одинаковые остатки, поэтому <span class="m">a<sub>2</sub> + a<sub>3</sub> = 4 + 1 = 5</span> делится на 5.</p></div>
<h3>Соседние числа</h3>
<p>Если из чисел 1, 2, …, 20 выбрать 11, то среди них найдутся два соседних (разбей числа на пары (1, 2), (3, 4), …, (19, 20) — их 10). Соседние числа взаимно просты: их общий делитель делит разность 1.</p>
<h3>Последовательности по модулю</h3>
<p>Последние цифры степеней двойки: 2, 4, 8, 6, 2, 4, … Каждый следующий остаток определяется предыдущим, а остатков конечное число, поэтому по принципу Дирихле какой-то остаток повторится, и дальше всё пойдёт по кругу. Такая последовательность обязательно периодична (возможно, после нескольких первых членов).</p>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Когда нужна делимость суммы — смотри на суммы подряд или на остатки. Когда нужно «одно делится на другое» — запиши каждое число как <span class="m">2<sup>k</sup> · m</span> с нечётным m и сделай клетками нечётные части.</p></div>` },

      { id: 'pg-l4', title: 'Принцип Дирихле в геометрии', mins: 14, html: `
<p>Клетками в геометрии служат части фигуры. Если в одной части оказались две точки, расстояние между ними не больше диаметра части (наибольшего расстояния между её точками).</p>
${figSq}
<div class="ex"><div class="ex-h">Пример</div>
<p>В квадрате 3 × 3 отмечено 10 точек. Разобьём его на 9 единичных квадратиков. Какие-то две точки попадут в один квадратик, и расстояние между ними не больше его диагонали <span class="m">${sq('2')}</span>.</p></div>
<h3>Длины и площади</h3>
<div class="box"><div class="box-h">Непрерывный принцип Дирихле</div>
<p>Если внутри отрезка длины L лежат отрезки суммарной длины больше L, то какие-то два из них перекрываются. Если внутри фигуры площади S лежат фигуры суммарной площади больше S, то какие-то две перекрываются.</p></div>
<p>Пример: в квадрат 1 × 1 положили три фигуры площади 0,4. Сумма площадей 1,2 > 1, значит, какие-то две перекрываются.</p>
<h3>Проекции</h3>
<p>Иногда клетки — точки стороны квадрата, а кролики — проекции фигур на неё. Пусть внутри квадрата 1 × 1 лежат отрезки суммарной длины 2,5. Каждый отрезок длины d проектируется на две соседние стороны отрезками, сумма длин которых не меньше d. Значит, на одну из сторон проекции в сумме не короче 1,25 > 1, и какие-то две проекции перекрываются. Прямая, перпендикулярная этой стороне и проходящая через общую точку проекций, пересекает два отрезка.</p>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Делить фигуру нужно на части, диаметр которых равен нужному расстоянию. Сначала найди пример расположения с меньшим числом точек — по нему видно, какие части выбрать.</p></div>` },

      { id: 'pg-l5', title: 'Знакомства и раскраски', mins: 12, html: `
<h3>Одинаковое число знакомых</h3>
<div class="box"><div class="box-h">Теорема</div>
<p>В любой компании из n ≥ 2 человек найдутся двое с одинаковым числом знакомых в этой компании.</p></div>
<p>Доказательство: число знакомых — от 0 до n − 1, это n вариантов. Но 0 и n − 1 не встречаются одновременно: если кто-то знаком со всеми, то ни с кем не знакомых нет. Значит, вариантов на самом деле n − 1, а людей n.</p>
<p>Знакомства удобно рисовать графом: люди — точки, знакомые соединены линиями. Число знакомых — степень вершины.</p>
<h3>Раскраска плоскости</h3>
<p>Каждую точку плоскости покрасили в один из двух цветов. Тогда найдутся две точки одного цвета на расстоянии ровно 1: возьмём правильный треугольник со стороной 1 — из трёх вершин две одного цвета.</p>
<h3>Шесть человек</h3>
<p>Знаменитый факт: в любой компании из шести человек есть трое попарно знакомых или трое попарно незнакомых. Его доказательство — одна из задач этой темы. Подсказка к ней: начни с одного человека и посмотри на пятерых остальных.</p>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Если в задаче про знакомства нужно найти «много одинаковых», начни с одной вершины: её рёбра разбиваются по цветам (знаком / незнаком), и по принципу Дирихле рёбер одного цвета много. Дальше смотри на концы этих рёбер.</p></div>` },

      { id: 'pg-l6', title: 'Олимпиадные приёмы', mins: 14, html: `
<h3>Пары</h3>
<p>Если нужно найти два числа с суммой s, разбей все числа на пары с суммой s: <span class="m">(1, s − 1), (2, s − 2), …</span> Например, числа 1, …, 100 разбиваются на 50 пар с суммой 101, поэтому среди любых 51 из них есть два с суммой 101.</p>
<h3>Цепочки</h3>
<p>Если запрещено брать два числа, связанных правилом («отличаются на d», «одно вдвое больше другого»), разбей числа на цепочки, где соседние связаны этим правилом. В цепочке из L чисел без двух соседних можно взять не больше половины, округлённой вверх.</p>
<div class="ex"><div class="ex-h">Пример</div>
<p>Сколько чисел можно выбрать из 1, …, 20, чтобы никакие два не отличались на 5? Цепочки: (1, 6, 11, 16), (2, 7, 12, 17), …, (5, 10, 15, 20) — пять цепочек по 4 числа. В каждой можно взять не больше двух, всего не больше 10, и 10 достигается: 1, 2, 3, 4, 5, 11, 12, 13, 14, 15.</p></div>
<h3>Периодичность</h3>
<p>Если каждый член последовательности остатков определяется двумя предыдущими, то пар «соседних остатков» конечное число, какая-то пара повторится, и последовательность станет периодической. Так доказывают, что остатки чисел Фибоначчи по любому модулю периодичны.</p>
<h3>Точность оценки</h3>
<p>Принцип Дирихле даёт оценку, но не говорит, достигается ли она. В ответе всегда нужен пример: «больше нельзя» доказывает Дирихле, «столько можно» — построение.</p>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Иногда клеток слишком много и Дирихле не срабатывает. Тогда выбрось один объект (или сгруппируй объекты), чтобы остальные разбились на меньшее число групп, — и примени принцип к оставшимся.</p></div>` }
    ],

    problems: [
      // ── Уровень 1 · База ──
      { id: 'pg-01', lvl: 1, r: 800, type: 'num', q: `В классе 30 учеников. Какое наибольшее число k можно гарантировать: обязательно найдётся месяц, в котором родились хотя бы k учеников этого класса?`, a: ['3'],
        hints: [`Месяцы — клетки, ученики — кролики. 30 : 12 — округли вверх.`],
        sol: `Если бы в каждом месяце родилось не больше двух, учеников было бы не больше 24. Значит, в каком-то месяце не меньше трёх. Больше гарантировать нельзя: в шести месяцах по 3 ученика, в шести по 2. Ответ: 3.` },
      { id: 'pg-02', lvl: 1, r: 830, type: 'num', q: `В ящике 10 красных и 10 синих носков. Какое наименьшее число носков нужно взять не глядя, чтобы среди них наверняка оказались два носка одного цвета?`, a: ['3'],
        hints: [`Два носка могут оказаться разного цвета. А три?`],
        sol: `Два носка могут быть разного цвета. Из трёх носков двух цветов два одного цвета обязательно. Ответ: 3.` },
      { id: 'pg-03', lvl: 1, r: 860, type: 'num', q: `В том же ящике 10 красных и 10 синих носков. Какое наименьшее число носков нужно взять не глядя, чтобы среди них наверняка оказались два красных?`, a: ['12'],
        hints: [`Самый неудачный случай: все синие и один красный.`],
        sol: `Можно вытащить 10 синих и 1 красный — 11 носков без двух красных. Если взять 12, синих среди них не больше 10, значит, красных хотя бы 2. Ответ: 12.` },
      { id: 'pg-04', lvl: 1, r: 890, type: 'choice', q: `В школе 370 учеников. Какое из утверждений обязательно верно?`, opts: ['все родились в разные дни года', 'хотя бы двое родились в один и тот же день года', 'хотя бы трое родились в один и тот же день года', 'кто-то родился 29 февраля'], a: 1,
        hints: [`В году не больше 366 дней.`],
        sol: `Дней в году не больше 366, а учеников 370, поэтому хотя бы двое родились в один день. Троих гарантировать нельзя: 370 ≤ 2 · 366.` },
      { id: 'pg-05', lvl: 1, r: 920, type: 'num', q: `В мешке много шаров четырёх цветов. Какое наименьшее число шаров нужно вынуть не глядя, чтобы среди них наверняка нашлись три шара одного цвета?`, a: ['9'],
        hints: [`Сколько шаров можно вынуть так, чтобы каждого цвета было не больше двух?`],
        sol: `Можно вынуть по два шара каждого цвета — 8 шаров без трёх одноцветных. Из 9 шаров четырёх цветов какого-то цвета не меньше трёх (иначе шаров не больше 8). Ответ: 9.` },
      { id: 'pg-06', lvl: 1, r: 960, type: 'num', q: `Какое наименьшее количество целых чисел нужно взять, чтобы среди них наверняка нашлись два с одинаковым остатком при делении на 7?`, a: ['8'],
        hints: [`Остатков при делении на 7 ровно семь.`],
        sol: `Числа 0, 1, …, 6 дают семь разных остатков. Из восьми чисел два обязательно дают одинаковый остаток. Ответ: 8.` },
      { id: 'pg-07', lvl: 1, r: 1000, type: 'num', q: `В 5 коробках лежит 41 карандаш. Какое наибольшее число k можно гарантировать: в какой-то коробке обязательно не меньше k карандашей?`, a: ['9'],
        hints: [`41 : 5 = 8,2. Округли вверх.`],
        sol: `Если в каждой коробке не больше 8, всего не больше 40. Значит, в какой-то коробке хотя бы 9. Больше гарантировать нельзя: 9, 8, 8, 8, 8. Ответ: 9.` },
      { id: 'pg-08', lvl: 1, r: 1040, type: 'num', q: `На полке 7 книг по математике и 5 по физике. Какое наименьшее число книг нужно взять не глядя, чтобы среди них наверняка были книги по обоим предметам?`, a: ['8'],
        hints: [`Можно вытащить все книги по математике подряд.`],
        sol: `Можно взять 7 книг, и все окажутся по математике. Если взять 8, книг по математике среди них не больше 7, значит, есть и по физике. Ответ: 8.` },

      // ── Уровень 2 · Районный этап ──
      { id: 'pg-09', lvl: 2, r: 1070, type: 'num', q: `В ящике 5 красных, 7 синих и 9 зелёных шаров. Какое наименьшее число шаров нужно вынуть не глядя, чтобы среди них наверняка были шары всех трёх цветов?`, a: ['17'],
        hints: [`Самый неудачный случай: все шары двух самых многочисленных цветов.`],
        sol: `Можно вынуть все 7 синих и 9 зелёных — 16 шаров без красного. Если вынуть 17, то шаров любых двух цветов не больше 16, поэтому есть все три цвета. Ответ: 17.` },
      { id: 'pg-10', lvl: 2, r: 1100, type: 'num', q: `В том же ящике 5 красных, 7 синих и 9 зелёных шаров. Какое наименьшее число шаров нужно вынуть, чтобы среди них наверняка нашлись 4 шара одного цвета?`, a: ['10'],
        hints: [`Сколько можно вынуть, если каждого цвета брать не больше трёх?`],
        sol: `Можно вынуть по 3 шара каждого цвета — 9 шаров без четырёх одноцветных (шаров каждого цвета хватает). Из 10 шаров трёх цветов какого-то цвета не меньше 4. Ответ: 10.` },
      { id: 'pg-11', lvl: 2, r: 1130, type: 'num', q: `Какое наименьшее количество чисел из 1, 2, …, 20 нужно выбрать, чтобы среди выбранных наверняка нашлись два с суммой 21?`, a: ['11'],
        hints: [`Разбей числа на пары с суммой 21.`],
        sol: `Пары (1, 20), (2, 19), …, (10, 11) — их 10. Из 11 чисел два попадут в одну пару. А числа 1, 2, …, 10 — десять чисел без пары с суммой 21. Ответ: 11.` },
      { id: 'pg-12', lvl: 2, r: 1160, type: 'num', q: `В классе 25 учеников. Какое наибольшее число k можно гарантировать: обязательно найдутся k учеников, родившихся в один и тот же день недели?`, a: ['4'],
        hints: [`25 : 7 — округли вверх.`],
        sol: `Если на каждый день недели приходится не больше трёх, учеников не больше 21. Значит, в какой-то день родились хотя бы 4. Пример 4, 4, 4, 4, 3, 3, 3 показывает, что 5 не гарантируется. Ответ: 4.` },
      { id: 'pg-13', lvl: 2, r: 1190, type: 'num', q: `Какое наибольшее количество чисел можно выбрать из 1, 2, …, 30 так, чтобы никакие два выбранных не отличались на 1?`, a: ['15'],
        hints: [`Разбей числа на пары (1, 2), (3, 4), …`],
        sol: `В каждой из 15 пар (1, 2), (3, 4), …, (29, 30) можно взять не больше одного числа, поэтому выбранных не больше 15. Пример: все нечётные числа. Ответ: 15.` },
      { id: 'pg-14', lvl: 2, r: 1220, type: 'num', q: `Какое наименьшее количество точек нужно отметить на отрезке длины 1, чтобы среди них наверняка нашлись две на расстоянии не больше 0,2?`, a: ['6'],
        hints: [`Раздели отрезок на 5 частей длины 0,2.`, `Пять точек можно расставить с шагом 0,25.`],
        sol: `Точки 0; 0,25; 0,5; 0,75; 1 попарно удалены больше чем на 0,2 — пяти точек мало. Если точек 6, разобьём отрезок на 5 отрезков длины 0,2: в какой-то попадут две точки, и расстояние между ними не больше 0,2. Ответ: 6.` },
      { id: 'pg-15', lvl: 2, r: 1250, type: 'choice', q: `В коробке 50 конфет четырёх видов. Какое из утверждений обязательно верно?`, opts: ['каких-то конфет не меньше 13', 'каких-то конфет не меньше 14', 'конфет каждого вида не меньше 12', 'каких-то конфет ровно 13'], a: 0,
        hints: [`50 : 4 = 12,5. Проверь каждое утверждение на примерах 13, 13, 12, 12 и 50, 0, 0, 0.`],
        sol: `Если бы конфет каждого вида было не больше 12, всего было бы не больше 48. Значит, каких-то не меньше 13. Остальные утверждения опровергаются примерами: 13, 13, 12, 12 (нет 14) и 50, 0, 0, 0 (не каждого вида по 12 и нет ровно 13).` },
      { id: 'pg-16', lvl: 2, r: 1280, type: 'num', q: `Какое наименьшее число карт нужно взять не глядя из колоды в 36 карт (4 масти по 9 карт), чтобы среди них наверняка были карты всех четырёх мастей?`, a: ['28'],
        hints: [`Сколько карт можно взять, не взяв ни одной карты какой-то масти?`],
        sol: `Можно взять все 27 карт трёх мастей. Если взять 28, то карт любых трёх мастей не больше 27, значит, есть и четвёртая. Ответ: 28.` },
      { id: 'pg-17', lvl: 2, r: 1310, type: 'num', q: `В квадрате со стороной 1 отмечают точки. Какое наименьшее число точек гарантирует, что найдутся две на расстоянии не больше ${fr(sq('2'), '2')}?`, a: ['5'],
        hints: [`Четыре точки можно поставить в вершины.`, `Раздели квадрат на 4 квадратика со стороной ${fr('1', '2')}. Какова их диагональ?`],
        sol: `Четыре вершины квадрата попарно удалены не меньше чем на 1 > ${fr(sq('2'), '2')}. Если точек 5, разобьём квадрат на 4 квадратика со стороной ${fr('1', '2')}: две точки попадут в один, и расстояние между ними не больше его диагонали ${fr(sq('2'), '2')}. Ответ: 5.` },
      { id: 'pg-18', lvl: 2, r: 1340, type: 'num', q: `30 учеников написали диктант. Вася сделал 13 ошибок, а каждый из остальных — меньше. Какое наибольшее число k можно гарантировать: найдутся k учеников с одинаковым числом ошибок?`, a: ['3'],
        hints: [`У остальных 29 учеников от 0 до 12 ошибок — 13 вариантов.`],
        sol: `29 учеников (кроме Васи) распределены по 13 вариантам: 0, 1, …, 12 ошибок. Если бы в каждом было не больше двух, учеников было бы не больше 26. Значит, какой-то вариант встречается хотя бы трижды. Пример: по 3 ученика с 0, 1 и 2 ошибками и по 2 с остальными (3 · 3 + 10 · 2 = 29) — четверых нет. Ответ: 3.` },

      // ── Уровень 3 · Полуфинал ──
      { id: 'pg-19', lvl: 3, r: 1370, type: 'num', q: `Какое наименьшее n гарантирует, что из любых n целых чисел можно выбрать несколько (хотя бы одно), сумма которых делится на 7?`, a: ['7'],
        hints: [`Рассмотри суммы первых k чисел.`, `Шесть единиц — пример, где не получится.`],
        sol: `Из шести единиц любые несколько дают сумму от 1 до 6 — не делится на 7. Из семи чисел a<sub>1</sub>, …, a<sub>7</sub> рассмотрим суммы S<sub>k</sub> = a<sub>1</sub> + … + a<sub>k</sub>. Если какая-то делится на 7 — готово. Иначе семь сумм дают не больше шести ненулевых остатков, две суммы S<sub>i</sub> и S<sub>j</sub> (i < j) имеют одинаковый остаток, и a<sub>i+1</sub> + … + a<sub>j</sub> делится на 7. Ответ: 7.` },
      { id: 'pg-20', lvl: 3, r: 1400, type: 'num', q: `Какое наибольшее количество чисел можно выбрать из 1, 2, …, 50 так, чтобы ни одно выбранное число не делилось на другое выбранное?`, a: ['25'],
        hints: [`Попробуй числа от 26 до 50.`, `Запиши каждое число как 2<sup>k</sup> · m, где m нечётно. Сколько бывает нечётных m?`],
        sol: `Числа 26, 27, …, 50 подходят: частное двух из них меньше 2 и больше 1, значит, не целое. Это 25 чисел. Больше нельзя: запишем каждое число как 2<sup>k</sup> · m с нечётным m. Нечётных m от 1 до 49 ровно 25. Если выбрано 26 чисел, у двух одинаковое m, и меньшее из них делит большее. Ответ: 25.` },
      { id: 'pg-21', lvl: 3, r: 1430, type: 'num', q: `Какое наименьшее количество чисел нужно выбрать из 1, 2, …, 100, чтобы среди выбранных наверняка нашлись два взаимно простых?`, a: ['51'],
        hints: [`Есть 50 чисел, никакие два из которых не взаимно просты.`, `Пары (1, 2), (3, 4), …: соседние числа взаимно просты.`],
        sol: `Все 50 чётных чисел попарно не взаимно просты — пятидесяти мало. Из 51 числа два попадут в одну из 50 пар (1, 2), (3, 4), …, (99, 100), то есть окажутся соседними, а соседние числа взаимно просты. Ответ: 51.` },
      { id: 'pg-22', lvl: 3, r: 1460, type: 'num', q: `Какое наименьшее число людей должно быть в компании, чтобы в ней наверняка нашлись трое попарно знакомых или трое попарно незнакомых?`, a: ['6'],
        hints: [`Для пяти человек попробуй рассадить их по кругу: каждый знаком только с соседями.`, `Для шести возьми одного человека. Среди пятерых остальных он знаком хотя бы с тремя или не знаком хотя бы с тремя.`],
        sol: `Пять человек, сидящих по кругу, где каждый знаком только с двумя соседями, — нет ни троих знакомых, ни троих незнакомых. Пусть людей шесть; возьмём одного, A. По принципу Дирихле из остальных пятерых он знаком хотя бы с тремя или не знаком хотя бы с тремя; пусть знаком с B, C, D. Если какие-то двое из B, C, D знакомы, то вместе с A это трое знакомых. Если нет — B, C, D попарно незнакомы. Второй случай симметричен. Ответ: 6.` },
      { id: 'pg-23', lvl: 3, r: 1490, type: 'num', q: `Какое наименьшее n гарантирует, что среди любых n различных целых чисел найдутся два, сумма или разность которых делится на 10?`, a: ['7'],
        hints: [`Сумма делится на 10, если остатки дают в сумме 10 или оба 0; разность — если остатки равны.`, `Объедини остатки в группы {0}, {5}, {1, 9}, {2, 8}, {3, 7}, {4, 6}.`],
        sol: `Разобьём остатки при делении на 10 на 6 групп: {0}, {5}, {1, 9}, {2, 8}, {3, 7}, {4, 6}. Если два числа попали в одну группу, то при равных остатках их разность делится на 10, а при остатках r и 10 − r — сумма. Из 7 чисел два попадут в одну группу. Числа 0, 1, 2, 3, 4, 5 показывают, что шести мало: никакие два из них не дают суммы или разности, кратной 10. Ответ: 7.` },
      { id: 'pg-24', lvl: 3, r: 1520, type: 'num', q: `Какое наибольшее число королей можно расставить на шахматной доске 8 × 8 так, чтобы никакие два не били друг друга?`, a: ['16'],
        hints: [`Король бьёт все соседние клетки, в том числе по диагонали. Сколько королей помещается в квадрате 2 × 2?`],
        sol: `Разобьём доску на 16 квадратов 2 × 2. Любые две клетки квадрата соседние, поэтому в каждом квадрате не больше одного короля — всего не больше 16. Пример: короли на клетках, у которых номера строки и столбца нечётны. Ответ: 16.` },
      { id: 'pg-25', lvl: 3, r: 1550, type: 'num', q: `Клетки таблицы из 3 строк и n столбцов красят в два цвета. При каком наименьшем n в любой раскраске найдутся четыре клетки одного цвета в вершинах прямоугольника (две строки и два столбца)?`, a: ['7'],
        hints: [`В каждом столбце из трёх клеток две одного цвета. Назови «типом» столбца пару строк и цвет такой пары.`, `Типов 3 · 2 = 6. Для n = 6 найди раскраску, где все столбцы разных типов и нет прямоугольника.`],
        sol: `В каждом столбце какие-то две клетки одного цвета; пара строк (3 варианта) и цвет (2 варианта) дают 6 типов. Если столбцов 7, два столбца имеют общий тип, и эти четыре клетки — одноцветный прямоугольник. Для 6 столбцов прямоугольника может не быть: столбцы (сверху вниз, Б — белый, Ч — чёрный) ББЧ, БЧБ, ЧББ, ЧЧБ, ЧБЧ, БЧЧ — у каждого ровно одна одноцветная пара, и все они разные. Ответ: 7.` },
      { id: 'pg-26', lvl: 3, r: 1580, type: 'num', q: `Какое наименьшее количество натуральных чисел нужно взять, чтобы среди них наверняка нашлись два, разность квадратов которых делится на 10?`, a: ['7'],
        hints: [`a<sup>2</sup> − b<sup>2</sup> делится на 10, если квадраты дают одинаковый остаток при делении на 10. Какие последние цифры бывают у квадратов?`],
        sol: `Квадрат оканчивается на одну из цифр 0, 1, 4, 5, 6, 9 — шесть вариантов. Из семи чисел у двух квадраты оканчиваются одинаково, и разность квадратов делится на 10. Числа 1, 2, 3, 4, 5, 10 (квадраты 1, 4, 9, 16, 25, 100) показывают, что шести мало. Ответ: 7.` },
      { id: 'pg-27', lvl: 3, r: 1610, type: 'num', q: `В правильном треугольнике со стороной 1 отмечают точки. Какое наименьшее число точек гарантирует, что найдутся две на расстоянии не больше ${fr('1', '2')}?`, a: ['5'],
        hints: [`Средние линии делят треугольник на 4 правильных треугольника со стороной ${fr('1', '2')}.`, `Для четырёх точек возьми три вершины и центр.`],
        sol: `Три вершины и центр треугольника попарно удалены больше чем на ${fr('1', '2')}: от центра до вершины ${fr(sq('3'), '3')} ≈ 0,577. Если точек 5, разобьём треугольник средними линиями на 4 треугольника со стороной ${fr('1', '2')}: две точки попадут в один, и расстояние между ними не больше ${fr('1', '2')}. Ответ: 5.` },
      { id: 'pg-28', lvl: 3, r: 1640, type: 'num', q: `Числа 1, 2, …, n красят в два цвета. При каком наименьшем n в любой раскраске найдутся три числа одного цвета, образующие арифметическую прогрессию?`, a: ['9'],
        hints: [`Для n = 8 есть раскраска без одноцветной прогрессии: попробуй 1, 2, 5, 6 одного цвета, а 3, 4, 7, 8 — другого.`, `Для n = 9 разбери случаи: 4 и 6 одного цвета или разных.`],
        sol: `Раскраска «1, 2, 5, 6 — красные, 3, 4, 7, 8 — синие» не содержит одноцветной трёхчленной прогрессии (проверь все тройки). Значит, n ≥ 9. Докажем, что для 1, …, 9 одноцветная прогрессия есть всегда. Пусть её нет.<br><b>4 и 6 одного цвета</b>, скажем, красные. Тогда 5, 2 и 8 синие (из троек 4, 5, 6; 2, 4, 6; 4, 6, 8), а 2, 5, 8 — синяя прогрессия.<br><b>4 и 6 разного цвета.</b> Замена x → 10 − x переводит прогрессии в прогрессии, поэтому можно считать 4 красным, 6 синим.<br>Если 5 красное: 3 синее (3, 4, 5), 9 красное (3, 6, 9), 1 синее (1, 5, 9), 7 синее (5, 7, 9), 8 красное (6, 7, 8), 2 синее (2, 5, 8) — и 1, 2, 3 синие.<br>Если 5 синее: 7 красное (5, 6, 7), 1 синее (1, 4, 7), 9 красное (1, 5, 9), 8 синее (7, 8, 9), 2 красное (2, 5, 8), 3 синее (2, 3, 4) — и 1, 3, 5 синие.<br>Во всех случаях противоречие. Ответ: 9.` },

      // ── Уровень 4 · Финал ──
      { id: 'pg-29', lvl: 4, r: 1680, type: 'num', q: `Какое наименьшее количество чисел нужно выбрать из 1, 2, …, 100, чтобы среди выбранных наверняка нашлись два, отличающиеся ровно на 11?`, a: ['56'],
        hints: [`Разбей числа на цепочки по остаткам при делении на 11: (1, 12, 23, …, 100), (2, 13, …, 90), …`, `В цепочке из L чисел без двух соседних можно взять не больше половины, округлённой вверх.`],
        sol: `Числа с одинаковым остатком при делении на 11 образуют цепочку, где соседние отличаются на 11. Цепочка с остатком 1 — это 1, 12, …, 100 (10 чисел), остальные десять цепочек — по 9 чисел. Два числа, отличающиеся на 11, — соседи в своей цепочке. Без соседей из цепочки длины 10 можно взять 5, из цепочки длины 9 — 5 (через одно, начиная с первого). Всего не больше 5 + 10 · 5 = 55, и 55 достигается. Значит, 56 чисел гарантируют пару с разностью 11. Ответ: 56.` },
      { id: 'pg-30', lvl: 4, r: 1720, type: 'proof', q: `В квадрате со стороной 1 отмечена 51 точка. Докажите, что какие-то три из них можно накрыть кругом радиуса ${fr('1', '7')}.`,
        hints: [`Раздели квадрат на 25 квадратиков со стороной ${fr('1', '5')}.`, `В какой-то квадратик попадут три точки. Какого радиуса круг накрывает квадратик со стороной ${fr('1', '5')}?`],
        sol: `Разобьём квадрат на 25 квадратиков со стороной ${fr('1', '5')}. Так как 51 > 2 · 25, в какой-то квадратик попадут хотя бы три точки. Квадратик со стороной ${fr('1', '5')} накрывается описанным кругом радиуса ${fr(sq('2'), '10')}, а ${fr(sq('2'), '10')} < ${fr('1', '7')}, так как 7${sq('2')} < 10 (98 < 100). Значит, круг радиуса ${fr('1', '7')} с тем же центром накрывает эти три точки.`,
        rubric: [[2, `Квадрат разбит на 25 частей, по Дирихле в одной хотя бы 3 точки`], [3, `Радиус круга, описанного около квадратика, равен ${fr(sq('2'), '10')}`], [2, `Сравнение ${fr(sq('2'), '10')} < ${fr('1', '7')} и вывод`]] },
      { id: 'pg-31', lvl: 4, r: 1760, type: 'proof', q: `Внутри квадрата со стороной 1 лежат несколько кругов, сумма длин окружностей которых равна 10. Докажите, что найдётся прямая, пересекающая не менее четырёх из этих кругов.`,
        hints: [`Спроектируй круги на одну из сторон квадрата. Проекция круга — отрезок длины, равной диаметру.`, `Сумма диаметров равна ${fr('10', 'π')} > 3.`],
        sol: `Проекция круга диаметра d на сторону AB — отрезок длины d, а сумма диаметров равна ${fr('10', 'π')} > 3. Все проекции лежат на отрезке AB длины 1. Если бы каждая точка AB была покрыта не более чем тремя проекциями, сумма их длин была бы не больше 3. Значит, некоторая точка покрыта хотя бы четырьмя проекциями. Прямая, перпендикулярная AB и проходящая через эту точку, пересекает все четыре соответствующих круга.`,
        rubric: [[2, `Круги спроектированы на сторону, сумма длин проекций ${fr('10', 'π')}`], [3, `Обосновано, что какая-то точка покрыта не менее чем четырьмя проекциями`], [2, `Построена перпендикулярная прямая, вывод`]] },
      { id: 'pg-32', lvl: 4, r: 1800, type: 'proof', q: `За круглым столом 8 мест, на каждом — карточка с именем гостя. Гости сели так, что никто не оказался перед своей карточкой. Докажите, что стол можно повернуть так, чтобы хотя бы двое гостей оказались перед своими карточками.`,
        hints: [`Сколько существует поворотов стола? Сколько из них не тождественные?`, `Каждый гость оказывается перед своей карточкой ровно при одном повороте.`],
        sol: `Повороты стола: на 0, 1, …, 7 мест. Каждый гость оказывается перед своей карточкой ровно при одном повороте, и это не поворот на 0 (в начале никто не сидит на своём месте). Получаем 8 «совпадений», распределённых по 7 ненулевым поворотам. По принципу Дирихле при каком-то повороте совпадений хотя бы два.`,
        rubric: [[2, `Каждому гостю сопоставлен единственный поворот, при котором он на своём месте`], [2, `Замечено, что тождественный поворот не подходит`], [3, `Принцип Дирихле: 8 совпадений на 7 поворотов, вывод`]] },
      { id: 'pg-33', lvl: 4, r: 1840, type: 'num', q: `Какое наибольшее количество чисел можно выбрать из 1, 2, …, 100 так, чтобы сумма никаких двух выбранных не делилась на 7?`, a: ['45'],
        hints: [`Сгруппируй числа по остаткам при делении на 7. Сколько чисел с каждым остатком?`, `Из остатков 1 и 6 можно брать только один, так же 2 и 5, 3 и 4. А чисел, делящихся на 7, — не больше одного.`],
        sol: `Остаток 0 у 14 чисел, остатки 1 и 2 — у 15 чисел, остатки 3, 4, 5, 6 — у 14 чисел. Два числа с остатками r и 7 − r дают сумму, кратную 7, поэтому из пар остатков (1, 6), (2, 5), (3, 4) берём числа только одного остатка; два числа, делящиеся на 7, тоже нельзя. Значит, выбрано не больше 15 + 15 + 14 + 1 = 45. Пример: все числа с остатками 1, 2, 3 и число 7 — суммы двух дают остатки 2, 3, 4, 5, 6 и 1, 2, 3 (с семёркой), не 0. Ответ: 45.` },
      { id: 'pg-34', lvl: 4, r: 1880, type: 'proof', q: `На шахматной доске 8 × 8 стоят 33 ладьи. Докажите, что можно выбрать 5 из них, никакие две из которых не бьют друг друга.`,
        hints: [`Разбей доску на 8 «ломаных диагоналей»: клетки (i, i + k), где номер столбца берётся по модулю 8.`, `В каждой ломаной диагонали по одной клетке в каждой строке и каждом столбце.`],
        sol: `Пронумеруем строки и столбцы от 0 до 7 и разобьём доску на 8 групп: в группу k (k = 0, …, 7) входят клетки (i, j), для которых j − i даёт остаток k при делении на 8. В каждой группе по одной клетке в каждой строке и в каждом столбце. Так как 33 > 4 · 8, в какой-то группе не меньше 5 ладей. Они стоят в разных строках и разных столбцах и не бьют друг друга.`,
        rubric: [[3, `Доска разбита на 8 групп, в каждой по клетке в каждой строке и столбце`], [2, `По принципу Дирихле в одной группе не меньше 5 ладей`], [2, `Вывод: ладьи из одной группы не бьют друг друга`]] },
      { id: 'pg-35', lvl: 4, r: 1920, type: 'proof', q: `В клетках таблицы 10 × 10 записаны натуральные числа, причём числа в соседних по стороне клетках отличаются не больше чем на 5. Докажите, что какие-то два числа таблицы равны.`,
        hints: [`Рассмотри клетки с наименьшим и наибольшим числами. За сколько шагов по соседним клеткам можно дойти от одной до другой?`, `Не больше чем за 18 шагов. Значит, наибольшее минус наименьшее не больше 90.`],
        sol: `Пусть m — наименьшее число, M — наибольшее. От клетки с m до клетки с M можно дойти по соседним клеткам не больше чем за 9 + 9 = 18 шагов, и на каждом шаге число меняется не больше чем на 5. Поэтому M − m ≤ 90, и все 100 чисел принимают не больше 91 значения (от m до m + 90). По принципу Дирихле два числа совпадают.`,
        rubric: [[2, `Рассмотрены наименьшее и наибольшее числа и путь между ними`], [3, `Доказано M − m ≤ 90`], [2, `Принцип Дирихле: 100 чисел и не больше 91 значения`]] },
      { id: 'pg-36', lvl: 4, r: 1950, type: 'num', q: `Числа 1, 2, …, 10 расставлены по кругу в произвольном порядке. Какое наибольшее число k можно гарантировать: обязательно найдутся три соседних числа с суммой не меньше k?`, a: ['18'],
        hints: [`Сумма всех десяти троек равна 3 · 55 = 165, но это даёт только 17. Можно лучше.`, `Убери число 1. Оставшиеся 9 мест разбиваются на 3 непересекающиеся тройки соседних.`],
        sol: `Уберём из круга число 1. Остальные 9 чисел стоят на 9 местах подряд, их можно разбить на три тройки соседних. Сумма этих девяти чисел 55 − 1 = 54, поэтому в одной из троек сумма не меньше 18. Больше гарантировать нельзя: в расстановке 1, 7, 9, 2, 6, 4, 8, 5, 3, 10 суммы соседних троек равны 17, 18, 17, 12, 18, 17, 16, 18, 14, 18 — наибольшая 18. Ответ: 18.` },

      // ── Уровень 5 · Международный ──
      { id: 'pg-37', lvl: 5, r: 2060, type: 'num', q: `Какое наименьшее n гарантирует, что из любых n целых чисел можно выбрать четыре, сумма которых делится на 4?`, a: ['7'],
        hints: [`Шесть чисел 0, 0, 0, 1, 1, 1 — пример, где не получается.`, `Сначала научись выбирать два числа с чётной суммой: из любых трёх чисел это возможно.`, `Из семи чисел трижды выбери пары с чётной суммой. Суммы пар — это 2b<sub>1</sub>, 2b<sub>2</sub>, 2b<sub>3</sub>. Что можно сказать о b<sub>1</sub>, b<sub>2</sub>, b<sub>3</sub>?`],
        sol: `Из шести чисел 0, 0, 0, 1, 1, 1 любые четыре дают сумму 1, 2 или 3 — не кратную 4. Пусть чисел семь. Из любых трёх чисел два одной чётности (по принципу Дирихле), их сумма чётна. Выберем такую пару из семи чисел, потом из пяти оставшихся, потом из трёх оставшихся — получим три непересекающиеся пары с суммами 2b<sub>1</sub>, 2b<sub>2</sub>, 2b<sub>3</sub>. Среди b<sub>1</sub>, b<sub>2</sub>, b<sub>3</sub> два одной чётности, например b<sub>1</sub> + b<sub>2</sub> чётно. Тогда четыре числа из первых двух пар имеют сумму 2(b<sub>1</sub> + b<sub>2</sub>), кратную 4. Ответ: 7.` },
      { id: 'pg-38', lvl: 5, r: 2150, type: 'proof', q: `Докажите, что у любого выпуклого многогранника есть две грани с одинаковым числом сторон.`,
        hints: [`Возьми грань с наибольшим числом сторон k.`, `У неё k соседних граней (по одной на каждое ребро). Сколько сторон может быть у каждой из них?`],
        sol: `Пусть наибольшее число сторон у грани равно k, и такая грань — G. По каждому из k рёбер к G примыкает соседняя грань, и все они различны (две грани выпуклого многогранника имеют не больше одного общего ребра). У каждой соседней грани от 3 до k сторон — это k − 2 варианта. Граней k, вариантов k − 2 < k, поэтому у двух соседних граней число сторон одинаково.`,
        rubric: [[2, `Рассмотрена грань с наибольшим числом сторон k`], [2, `У неё k различных соседних граней`], [2, `У каждой из них от 3 до k сторон — k − 2 варианта`], [1, `Принцип Дирихле, вывод`]] },
      { id: 'pg-39', lvl: 5, r: 2240, type: 'proof', q: `(Международная олимпиада, 1972) Дано 10 различных двузначных чисел. Докажите, что из них можно выбрать два непересекающихся подмножества с одинаковой суммой элементов.`,
        hints: [`Сколько у множества из 10 элементов непустых подмножеств? А какие бывают суммы?`, `Сумма любого подмножества не больше 10 · 99 = 990.`, `Найдя два разных подмножества с равными суммами, выкинь из обоих общие элементы.`],
        sol: `У множества из 10 чисел 2<sup>10</sup> − 1 = 1023 непустых подмножества. Сумма каждого — натуральное число от 10 до 990, то есть меньше 1023 вариантов. По принципу Дирихле у двух разных подмножеств A и B суммы равны. Выбросим из A и B их общие элементы: суммы уменьшатся на одно и то же число и останутся равными, а множества станут непересекающимися. Оба останутся непустыми: если бы одно стало пустым, сумма второго была бы 0, а оно непусто (A ≠ B), и его сумма положительна.`,
        rubric: [[2, `Подсчитано число непустых подмножеств (1023)`], [2, `Оценены суммы (не больше 990), принцип Дирихле`], [2, `Удалены общие элементы, суммы остаются равными`], [1, `Обосновано, что оба подмножества непусты`]] },
      { id: 'pg-40', lvl: 5, r: 2350, type: 'proof', q: `Каждую точку плоскости покрасили в один из трёх цветов. Докажите, что найдутся две точки одного цвета на расстоянии ровно 1.`,
        hints: [`Предположи противное. Возьми ромб ABCD из двух правильных треугольников ABC и BCD со стороной 1. Какого цвета A и D?`, `AD = ${sq('3')}. Значит, любые две точки на расстоянии ${sq('3')} одного цвета.`, `На окружности радиуса ${sq('3')} с центром A есть две точки на расстоянии 1.`],
        sol: `Предположим, что любые две точки на расстоянии 1 разноцветны. Возьмём ромб ABCD из правильных треугольников ABC и BCD со стороной 1. В треугольнике ABC три вершины трёх разных цветов, в треугольнике BCD тоже, причём B и C у них общие. Значит, A и D одного цвета, а AD = ${sq('3')}. Итак, любые две точки на расстоянии ${sq('3')} одного цвета. Возьмём окружность радиуса ${sq('3')} с центром A: все её точки цвета A. Но на ней есть две точки на расстоянии 1 (хорда длины 1 < 2${sq('3')}), и они одного цвета — противоречие.`,
        rubric: [[2, `Построен ромб из двух правильных треугольников, A и D одного цвета`], [2, `Вывод: точки на расстоянии ${sq('3')} одного цвета`], [2, `Окружность радиуса ${sq('3')} и хорда длины 1`], [1, `Противоречие`]] }
    ]
  });
})();

// ---- content/pigeon-deep.js ----
// Глубокий уровень темы «Принцип Дирихле».
// Дирихле в теории чисел, теорема Эрдёша — Секереша, усреднение и непрерывный принцип Дирихле.
(function () {
  function fr(a, b) { return '<span class="fr"><span>' + a + '</span><span>' + b + '</span></span>'; }
  function sq(x) { return '<span class="sq">√<span>' + x + '</span></span>'; }

  MM.addDeep('pigeon', {
    lessons: [
      { id: 'pg-l7', title: 'Дирихле в теории чисел', mins: 16, html: `
<h3>Повторение остатков и сокращение</h3>
<p>Рассмотрим степени <span class="m">2<sup>1</sup>, 2<sup>2</sup>, …, 2<sup>10</sup></span> по модулю 9. Остатков всего 9, поэтому два из десяти совпадут: <span class="m">2<sup>i</sup> ≡ 2<sup>j</sup></span>, i < j. Значит, <span class="m">2<sup>i</sup>(2<sup>j − i</sup> − 1)</span> делится на 9, а так как 2 и 9 взаимно просты, <span class="m">2<sup>j − i</sup> ≡ 1 (mod 9)</span>. (На самом деле <span class="m">2<sup>6</sup> = 64 = 7 · 9 + 1</span>.)</p>
<div class="box"><div class="box-h">Схема</div>
<p>Принцип Дирихле даёт <b>повторение</b>, а взаимная простота позволяет <b>сократить</b> и превратить повторение в равенство с единицей (или нулём).</p></div>
<h3>Обратимые последовательности</h3>
<p>Если каждый член последовательности остатков однозначно определяет и следующий, и предыдущий, то последовательность периодична с самого начала (без «предпериода»): после первого повторения можно идти назад и дойти до начала. Например, остатки <span class="m">2<sup>n</sup></span> по модулю 9 периодичны с самого начала, а по модулю 8 — нет (2, 4, 0, 0, …): умножение на 2 по модулю 8 необратимо.</p>
<h3>Теорема Дирихле о приближениях</h3>
<div class="box"><div class="box-h">Теорема</div>
<p>Для любого действительного α и натурального N найдётся натуральное <span class="m">q ≤ N</span>, при котором <span class="m">qα</span> отличается от ближайшего целого меньше чем на <span class="m">${fr('1', 'N')}</span>.</p></div>
<p>Доказательство: дробные части чисел <span class="m">0 · α, 1 · α, …, N · α</span> — это N + 1 точка отрезка [0; 1). Разобьём его на N полуинтервалов длины <span class="m">${fr('1', 'N')}</span>. Две точки, <span class="m">iα</span> и <span class="m">jα</span> (i < j), попадут в один, и разность <span class="m">(j − i)α</span> отличается от целого меньше чем на <span class="m">${fr('1', 'N')}</span>. Берём q = j − i.</p>
<h3>Иррациональные шаги</h3>
<p>Если α иррационально, дробные части <span class="m">qα</span> никогда не равны нулю. По теореме есть q, у которого дробная часть qα — маленькое число ε (или близка к 1). Тогда числа <span class="m">qα, 2qα, 3qα, …</span> идут по кругу [0; 1) шагами длины ε и не могут «перепрыгнуть» ни через один отрезок длины больше ε. Поэтому дробные части <span class="m">nα</span> попадают в любой, сколь угодно маленький отрезок.</p>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Задачи «докажите, что существует число вида …» часто решаются так: возьми достаточно много кандидатов, найди два с одинаковым остатком (или близкими дробными частями) и рассмотри их разность.</p></div>` },

      { id: 'pg-l8', title: 'Теорема Эрдёша — Секереша', mins: 16, html: `
<p>Подпоследовательность — это несколько членов, взятых в исходном порядке, но не обязательно подряд.</p>
<div class="box"><div class="box-h">Теорема Эрдёша — Секереша</div>
<p>В любой последовательности из <span class="m">n<sup>2</sup> + 1</span> различных чисел есть возрастающая или убывающая подпоследовательность из n + 1 члена.</p></div>
<h3>Доказательство «стопками»</h3>
<p>Раскладываем числа по очереди в стопки. Каждое число кладём наверх самой левой стопки, верхнее число которой больше него; если такой нет — начинаем справа новую стопку. В каждой стопке числа сверху вниз возрастают, то есть в порядке появления убывают: каждая стопка — убывающая подпоследовательность.</p>
<p>Когда число кладётся в стопку номер k > 1, в стопке k − 1 наверху лежит меньшее число (иначе наше число попало бы туда), и оно появилось раньше. Отметим его стрелкой. Идя по стрелкам от любого числа последней стопки, получаем возрастающую подпоследовательность, длина которой равна числу стопок.</p>
<p>Если возрастающей подпоследовательности из n + 1 члена нет, стопок не больше n. Тогда по принципу Дирихле в какой-то стопке не меньше n + 1 числа из <span class="m">n<sup>2</sup> + 1</span>, и это убывающая подпоследовательность нужной длины.</p>
<h3>Оценка точная</h3>
<p>Последовательность 7, 8, 9, 4, 5, 6, 1, 2, 3 (n = 3, девять чисел) не содержит ни возрастающей, ни убывающей подпоследовательности из четырёх членов: возрастающая берёт числа только из одного блока, убывающая — по одному из каждого блока. Так же строится пример из <span class="m">n<sup>2</sup></span> чисел для любого n.</p>
<h3>Тот же принцип в других местах</h3>
<p>Теорема — частный случай общего факта: если объекты нельзя выстроить в длинную «цепочку», их можно разбить на мало «слоёв», и тогда один слой большой. Так, из любых десяти натуральных чисел можно выбрать либо четыре, каждое из которых делится на предыдущее, либо четыре, никакое из которых не делится на другое.</p>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Припиши каждому члену последовательности «метку» — например, длины самых длинных возрастающей и убывающей подпоследовательностей, оканчивающихся на нём. Если метки разных членов различны, а меток мало, получаешь противоречие по принципу Дирихле.</p></div>` },

      { id: 'pg-l9', title: 'Усреднение и непрерывный принцип Дирихле', mins: 16, html: `
<h3>Усреднение по всем вариантам</h3>
<p>Чтобы доказать, что в одном из вариантов «хорошего» много, посчитай, сколько «хорошего» во всех вариантах вместе, и раздели на число вариантов: где-то не меньше среднего.</p>
<div class="ex"><div class="ex-h">Пример: два диска</div>
<p>Два одинаковых диска разбиты на 200 равных секторов. На первом 100 секторов красные и 100 синие, на втором каждый сектор красный или синий как угодно. Наложим второй диск на первый всеми 200 поворотами. Каждый сектор второго диска при 100 поворотах лежит на секторе своего цвета (ровно половина секторов первого диска — каждого цвета). Всего совпадений по всем поворотам <span class="m">200 · 100</span>, в среднем 100 на поворот. Значит, есть поворот, при котором совпадают не меньше 100 секторов.</p></div>
<h3>Двойной подсчёт</h3>
<p>Часто одну сумму считают двумя способами: «по строкам» и «по столбцам». Например, если в классе каждый из 30 учеников знает 4 языка из 10, то пар «ученик — язык» 120, и какой-то язык знают не меньше 12 учеников.</p>
<h3>Непрерывный вариант</h3>
<p>Если на окружности длины 1 нарисованы дуги суммарной длины 2,5, то какая-то точка покрыта не менее чем тремя дугами: «средняя кратность покрытия» равна 2,5, а кратность — целое число. Так же с отрезками и площадями: если фигуры суммарной площади больше kS лежат в фигуре площади S, то какая-то точка покрыта не менее чем k + 1 фигурой.</p>
<h3>Сдвиг по модулю</h3>
<p>Важный приём: сложить все куски фигуры «в одну клетку». Разрежем фигуру сеткой на куски и сдвинем каждый кусок в одну и ту же клетку сетки. Если площадь фигуры больше площади клетки, два куска наложатся. Этот приём ведёт к теоремам Блихфельдта и Минковского о точках решётки.</p>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Не можешь указать хороший вариант явно — усредни по всем вариантам. Существование докажется, а строить ничего не придётся.</p></div>` }
    ],

    problems: [
      // ── Уровень 4 · Финал ──
      { id: 'pg-41', lvl: 4, r: 1960, type: 'num', q: `Какое наименьшее n гарантирует, что в любой последовательности из n различных чисел найдутся 4 члена, идущих (не обязательно подряд) в порядке возрастания или в порядке убывания?`, a: ['10'],
        hints: [`Теорема Эрдёша — Секереша при n = 3.`, `Для 9 чисел вспомни пример из блоков.`],
        sol: `По теореме Эрдёша — Секереша при 3<sup>2</sup> + 1 = 10 членах монотонная подпоследовательность из 4 членов есть всегда. Последовательность 7, 8, 9, 4, 5, 6, 1, 2, 3 из девяти чисел такой подпоследовательности не имеет. Ответ: 10.` },
      { id: 'pg-42', lvl: 4, r: 1970, type: 'num', q: `Какое наименьшее натуральное N обладает свойством: для любого действительного α найдётся натуральное q ≤ N, при котором число qα отличается от ближайшего целого меньше чем на 0,1?`, a: ['10'],
        hints: [`Теорема Дирихле о приближениях с N = 10 показывает, что 10 подходит.`, `Подбери α, при котором для q = 1, …, 9 все числа qα удалены от целых не меньше чем на 0,1.`],
        sol: `N = 10 подходит: дробные части 0, α, 2α, …, 10α — 11 точек в 10 полуинтервалах длины 0,1, две попадут в один, и их разность qα (1 ≤ q ≤ 10) отличается от целого меньше чем на 0,1. N = 9 не подходит: при α = 0,1 числа qα = 0,1; 0,2; …; 0,9 удалены от ближайшего целого не меньше чем на 0,1. Ответ: 10.` },
      { id: 'pg-43', lvl: 4, r: 1980, type: 'proof', q: `Числа Фибоначчи: F<sub>1</sub> = F<sub>2</sub> = 1, F<sub>n+2</sub> = F<sub>n+1</sub> + F<sub>n</sub>. Докажите, что среди них есть число, делящееся на 2026.`,
        hints: [`Рассмотри пары остатков (F<sub>n</sub>, F<sub>n+1</sub>) при делении на 2026. Сколько бывает разных пар?`, `Две пары совпадут. Иди назад по формуле F<sub>n−1</sub> = F<sub>n+1</sub> − F<sub>n</sub>.`, `Удобно добавить F<sub>0</sub> = 0.`],
        sol: `Положим F<sub>0</sub> = 0, тогда формула верна и для n = 0. Пар остатков (F<sub>n</sub> mod 2026, F<sub>n+1</sub> mod 2026) не больше 2026<sup>2</sup>, поэтому среди первых 2026<sup>2</sup> + 1 пар две совпадают: (F<sub>i</sub>, F<sub>i+1</sub>) ≡ (F<sub>j</sub>, F<sub>j+1</sub>), i < j. Так как F<sub>n−1</sub> = F<sub>n+1</sub> − F<sub>n</sub>, остатки пары определяют остатки предыдущей пары, и, спускаясь, получаем (F<sub>0</sub>, F<sub>1</sub>) ≡ (F<sub>j−i</sub>, F<sub>j−i+1</sub>). Значит, F<sub>j−i</sub> ≡ F<sub>0</sub> = 0, где j − i ≥ 1: число F<sub>j−i</sub> делится на 2026.`,
        rubric: [[2, `Рассмотрены пары соседних остатков, по Дирихле две пары совпадают`], [3, `Обоснован спуск назад: пара остатков определяет предыдущую`], [2, `Получено F<sub>j−i</sub> ≡ 0, вывод`]] },
      { id: 'pg-44', lvl: 4, r: 1990, type: 'num', q: `Какое наименьшее количество точек с целыми координатами в пространстве нужно взять, чтобы среди них наверняка нашлись две, середина отрезка между которыми тоже имеет целые координаты?`, a: ['9'],
        hints: [`Середина имеет целые координаты, если у концов соответствующие координаты одной чётности.`, `Сколько бывает наборов чётностей (x, y, z)?`],
        sol: `Середина отрезка между (x<sub>1</sub>, y<sub>1</sub>, z<sub>1</sub>) и (x<sub>2</sub>, y<sub>2</sub>, z<sub>2</sub>) целая, если x<sub>1</sub>, x<sub>2</sub> одной чётности, и так же для y и z. Наборов чётностей 2<sup>3</sup> = 8, поэтому из 9 точек у двух набор одинаков. Восемь вершин куба с координатами 0 и 1 — пример, где середины не целые. Ответ: 9.` },
      { id: 'pg-45', lvl: 4, r: 2000, type: 'proof', q: `Докажите, что в любой последовательности из mn + 1 различных чисел есть возрастающая подпоследовательность из m + 1 члена или убывающая подпоследовательность из n + 1 члена.`,
        hints: [`Сопоставь k-му члену пару (a<sub>k</sub>, b<sub>k</sub>): длины самых длинных возрастающей и убывающей подпоследовательностей, оканчивающихся на нём.`, `Докажи, что у разных членов пары разные.`],
        sol: `Для k-го члена x<sub>k</sub> пусть a<sub>k</sub> — длина самой длинной возрастающей подпоследовательности, оканчивающейся на x<sub>k</sub>, а b<sub>k</sub> — самой длинной убывающей. Пусть k < l. Если x<sub>k</sub> < x<sub>l</sub>, то x<sub>l</sub> продолжает любую возрастающую подпоследовательность, оканчивающуюся на x<sub>k</sub>, и a<sub>l</sub> ≥ a<sub>k</sub> + 1. Если x<sub>k</sub> > x<sub>l</sub>, то так же b<sub>l</sub> ≥ b<sub>k</sub> + 1. Значит, пары (a<sub>k</sub>, b<sub>k</sub>) попарно различны. Если бы всегда a<sub>k</sub> ≤ m и b<sub>k</sub> ≤ n, различных пар было бы не больше mn, а членов mn + 1. Противоречие: какое-то a<sub>k</sub> ≥ m + 1 или b<sub>k</sub> ≥ n + 1.`,
        rubric: [[2, `Каждому члену сопоставлена пара длин`], [3, `Доказано, что пары различны`], [2, `Принцип Дирихле: mn пар на mn + 1 член, вывод`]] },
      { id: 'pg-46', lvl: 4, r: 2010, type: 'num', q: `Какое наименьшее число точек нужно отметить в круге радиуса 1 (внутри или на границе), чтобы среди них наверняка нашлись две на расстоянии меньше 1?`, a: ['8'],
        hints: [`Центр и шесть вершин вписанного правильного шестиугольника попарно удалены не меньше чем на 1.`, `Если точек 8, то хотя бы 7 из них не совпадают с центром. Посмотри на углы между лучами из центра.`],
        sol: `Центр и вершины вписанного правильного шестиугольника — 7 точек, попарные расстояния не меньше 1. Пусть точек 8. Хотя бы 7 из них отличны от центра O; лучи из O к ним делят полный угол на 7 частей, и какие-то две точки P, Q видны из O под углом не больше ${fr('360°', '7')} < 60°. В треугольнике OPQ угол O меньше 60°, поэтому он не наибольший, и сторона PQ не наибольшая: PQ < max(OP, OQ) ≤ 1. Ответ: 8.` },
      { id: 'pg-47', lvl: 4, r: 2030, type: 'num', q: `В шеренге стоят 50 человек разного роста. Какое наибольшее k можно гарантировать: всегда можно вывести из строя несколько человек так, чтобы остались k человек, стоящих по возрастанию или по убыванию роста?`, a: ['8'],
        hints: [`50 > 7<sup>2</sup>. Примени теорему Эрдёша — Секереша.`, `Для примера разбей 50 человек на 8 блоков: внутри блока по возрастанию, блоки — по убыванию.`],
        sol: `Так как 50 ≥ 7<sup>2</sup> + 1, по теореме Эрдёша — Секереша всегда есть монотонная подпоследовательность из 8 человек. Больше гарантировать нельзя: разобьём 50 человек на 8 блоков по 6 или 7 человек (6 · 6 + 7 · 2 = 50); в первом блоке самые высокие, в последнем самые низкие, а внутри блока рост возрастает. Возрастающая подпоследовательность лежит в одном блоке (не больше 7 человек), убывающая — по одному из блока (не больше 8). Ответ: 8.` },
      { id: 'pg-48', lvl: 4, r: 2050, type: 'proof', q: `Докажите, что существует степень тройки, десятичная запись которой оканчивается на 0001.`,
        hints: [`Рассмотри остатки 3<sup>1</sup>, 3<sup>2</sup>, …, 3<sup>10001</sup> при делении на 10 000.`, `Два совпадут: 3<sup>i</sup> ≡ 3<sup>j</sup>. Почему можно сократить на 3<sup>i</sup>?`],
        sol: `Среди 10 001 числа 3<sup>1</sup>, …, 3<sup>10001</sup> два дают одинаковый остаток при делении на 10 000: 3<sup>i</sup> ≡ 3<sup>j</sup>, i < j. Тогда 10 000 делит 3<sup>i</sup>(3<sup>j−i</sup> − 1). Число 3<sup>i</sup> взаимно просто с 10 000 = 2<sup>4</sup> · 5<sup>4</sup>, поэтому 10 000 делит 3<sup>j−i</sup> − 1, то есть 3<sup>j−i</sup> оканчивается на 0001.`,
        rubric: [[3, `Принцип Дирихле для остатков степеней`], [3, `Сокращение на 3<sup>i</sup> с обоснованием взаимной простоты`], [1, `Вывод про последние цифры`]] },

      // ── Уровень 5 · Международный ──
      { id: 'pg-49', lvl: 5, r: 2100, type: 'num', q: `Какое наименьшее число клеток таблицы 5 × 5 нужно закрасить, чтобы наверняка нашлись четыре закрашенные клетки в вершинах прямоугольника (на пересечении двух строк и двух столбцов)?`, a: ['13'],
        hints: [`Прямоугольника нет, если любые две строки имеют не больше одного общего закрашенного столбца. Посчитай пары закрашенных клеток в одной строке.`, `Строка с r закрашенными клетками даёт ${fr('r(r − 1)', '2')} пар столбцов. Всего пар столбцов 10, и каждая может встретиться только в одной строке.`, `Пример с 12 клетками: строки 11110, 10001, 01001, 00101, 00011.`],
        sol: `Если прямоугольника нет, каждая пара столбцов закрашена одновременно не более чем в одной строке. Строка с r закрашенными клетками содержит ${fr('r(r − 1)', '2')} пар, а всего пар столбцов 10. При 13 закрашенных клетках сумма ${fr('r(r − 1)', '2')} по строкам наименьшая, когда числа r ближе всего друг к другу: 3, 3, 3, 2, 2, и она равна 3 + 3 + 3 + 1 + 1 = 11 > 10 — противоречие. Двенадцати клеток мало: строки 11110, 10001, 01001, 00101, 00011 (1 — закрашена) попарно имеют ровно один общий столбец. Ответ: 13.` },
      { id: 'pg-50', lvl: 5, r: 2180, type: 'proof', q: `В строку выписаны 20 натуральных чисел с суммой 30. Докажите, что можно выбрать несколько чисел, стоящих подряд, с суммой ровно 10.`,
        hints: [`Рассмотри суммы S<sub>0</sub> = 0, S<sub>1</sub>, …, S<sub>20</sub> = 30 первых k чисел. Они различны.`, `Добавь к ним числа S<sub>0</sub> + 10, …, S<sub>20</sub> + 10. Сколько всего чисел и в каком они отрезке?`],
        sol: `Пусть S<sub>k</sub> — сумма первых k чисел, S<sub>0</sub> = 0. Числа возрастают: 0 = S<sub>0</sub> < S<sub>1</sub> < … < S<sub>20</sub> = 30 — это 21 различное число из отрезка [0; 30]. Числа S<sub>0</sub> + 10, …, S<sub>20</sub> + 10 — ещё 21 различное число из [10; 40]. Вместе 42 числа, а целых значений от 0 до 40 всего 41. Значит, какие-то два совпадают, причём из разных групп (внутри группы числа различны): S<sub>j</sub> = S<sub>i</sub> + 10. Тогда j > i и сумма чисел с номерами i + 1, …, j равна 10.`,
        rubric: [[2, `Введены суммы S<sub>k</sub>, отмечено, что они различны`], [2, `Добавлены сдвинутые суммы S<sub>k</sub> + 10`], [2, `Подсчёт: 42 числа на 41 значение`], [1, `Вывод про подряд идущие числа`]] },
      { id: 'pg-51', lvl: 5, r: 2260, type: 'proof', q: `(Международная олимпиада, 1964) Каждый из 17 учёных переписывается со всеми остальными. В переписке обсуждаются только три темы, и каждая пара учёных переписывается только на одну тему. Докажите, что найдутся трое учёных, которые попарно переписываются на одну и ту же тему.`,
        hints: [`Возьми одного учёного. С 16 остальными он переписывается на три темы. Сколько хотя бы на одну тему?`, `Хотя бы с шестью — на одну тему. Если двое из этих шести переписываются на ту же тему — готово.`, `Иначе шесть человек переписываются только на две темы. Вспомни задачу про шестерых знакомых.`],
        sol: `Возьмём учёного A. Из 16 его корреспондентов по принципу Дирихле хотя бы 6 переписываются с ним на одну тему, скажем, на тему 1. Если какие-то двое из этих шести тоже переписываются на тему 1, вместе с A получаем тройку. Если нет, эти шестеро переписываются между собой только на темы 2 и 3. В любой компании из шести человек при двух видах связей есть тройка, связанная попарно одним видом (задача о шестерых знакомых): берём одного из шести, у него хотя бы трое на одну тему, и далее как в той задаче. Так находим трёх учёных, попарно переписывающихся на тему 2 или 3.`,
        rubric: [[2, `Принцип Дирихле для одного учёного: 6 корреспондентов на одну тему`], [2, `Случай, когда двое из шести переписываются на ту же тему`], [3, `Сведение к задаче о шестерых с двумя темами и её решение`]] },
      { id: 'pg-52', lvl: 5, r: 2320, type: 'num', q: `Какое наименьшее n гарантирует, что среди любых n точек плоскости, никакие три из которых не лежат на одной прямой, найдутся четыре — вершины выпуклого четырёхугольника?`, a: ['5'],
        hints: [`Четыре точки: треугольник и точка внутри.`, `Для пяти точек рассмотри их выпуклую оболочку. Если в ней хотя бы 4 вершины — готово.`, `Если оболочка — треугольник с двумя точками внутри, проведи прямую через две внутренние точки.`],
        sol: `Вершины треугольника и точка внутри него — четыре точки без выпуклого четырёхугольника. Пусть точек пять. Если их выпуклая оболочка — пятиугольник или четырёхугольник, четыре её вершины образуют выпуклый четырёхугольник. Иначе оболочка — треугольник ABC, а точки D, E внутри. Прямая DE не проходит через вершины треугольника, и по одну сторону от неё лежат две вершины, скажем A и B. Покажем, что ни одна из точек A, B, D, E не лежит внутри треугольника из трёх остальных. A и B — вершины треугольника ABC, а все такие треугольники лежат внутри ABC, поэтому A и B внутри них быть не могут. Треугольник ABE лежит по одну сторону от прямой DE и касается её только в точке E, а D лежит на этой прямой — значит, D не внутри ABE; так же E не внутри ABD. Четыре точки, ни одна из которых не лежит внутри треугольника из остальных, — вершины выпуклого четырёхугольника. Ответ: 5.` },
      { id: 'pg-53', lvl: 5, r: 2380, type: 'proof', q: `Докажите, что существует натуральное n, для которого десятичная запись числа 2<sup>n</sup> начинается с цифр 2026.`,
        hints: [`2<sup>n</sup> начинается с 2026, если дробная часть числа n · lg 2 лежит в отрезке [lg 2,026; lg 2,027).`, `Число lg 2 иррационально. По теореме Дирихле найдётся q с дробной частью q · lg 2 меньше длины этого отрезка (или больше 1 минус длина).`, `Дробные части q · lg 2, 2q · lg 2, … идут по кругу маленькими шагами и не могут перепрыгнуть отрезок.`],
        sol: `2<sup>n</sup> начинается с 2026 ровно тогда, когда 2026 · 10<sup>k</sup> ≤ 2<sup>n</sup> < 2027 · 10<sup>k</sup> для некоторого k, то есть когда дробная часть {n lg 2} лежит в полуинтервале I = [lg 2,026; lg 2,027) длины δ > 0. Число lg 2 иррационально: из lg 2 = a/b следовало бы 2<sup>b</sup> = 10<sup>a</sup>, но 10<sup>a</sup> делится на 5. Возьмём N > 1/δ. По теореме Дирихле найдётся q ≤ N, при котором q lg 2 отличается от целого меньше чем на 1/N < δ; разность не ноль (иррациональность). Значит, дробные части q lg 2, 2q lg 2, 3q lg 2, … каждый раз сдвигаются по кругу [0; 1) на одно и то же расстояние ε < δ (вперёд или назад). Шагами меньше δ нельзя перепрыгнуть отрезок I длины δ, поэтому на каком-то шаге m дробная часть mq lg 2 попадёт в I. Берём n = mq.`,
        rubric: [[2, `Условие переведено в попадание {n lg 2} в отрезок длины δ`], [1, `Доказана иррациональность lg 2`], [2, `Найдено q с маленькой дробной частью q lg 2`], [2, `Шаги по кругу не перепрыгивают отрезок, вывод`]] },
      { id: 'pg-54', lvl: 5, r: 2440, type: 'proof', q: `(Теорема Блихфельдта) Фигура на плоскости имеет площадь больше 1. Докажите, что в ней найдутся две различные точки, у которых разности соответствующих координат — целые числа.`,
        hints: [`Разрежь плоскость линиями x = целое и y = целое на единичные квадраты.`, `Сдвинь каждый кусок фигуры на целый вектор в квадрат [0; 1) × [0; 1).`, `Сумма площадей кусков больше 1, а площадь квадрата 1.`],
        sol: `Разрежем плоскость на единичные квадраты [a; a + 1) × [b; b + 1) с целыми a, b. Фигура разбивается на куски, лежащие в разных квадратах. Сдвинем каждый кусок на целый вектор (−a; −b) в квадрат Q = [0; 1) × [0; 1). Сумма площадей кусков равна площади фигуры, то есть больше 1 = площадь Q. По непрерывному принципу Дирихле какие-то два сдвинутых куска пересекаются в точке P. Эти куски пришли из разных квадратов, поэтому P = A − u = B − v, где A, B — точки фигуры, а u ≠ v — целые векторы. Тогда A − B = u − v — ненулевой вектор с целыми координатами: точки A и B различны, а разности их координат целые.`,
        rubric: [[2, `Фигура разрезана на куски по единичным квадратам`], [2, `Куски сдвинуты на целые векторы в один квадрат`], [2, `Непрерывный принцип Дирихле: два куска пересекаются`], [1, `Вывод про две точки с целой разностью`]] },
      { id: 'pg-55', lvl: 5, r: 2490, type: 'proof', q: `(Международная олимпиада, 1985) Дано множество M из 1985 различных натуральных чисел, ни одно из которых не имеет простых делителей больше 23. Докажите, что в M найдутся четыре числа, произведение которых — четвёртая степень целого числа.`,
        hints: [`Простых чисел до 23 девять. Сопоставь числу вектор из 9 чётностей показателей. Сколько таких векторов?`, `Два числа с одинаковым вектором дают в произведении точный квадрат. Выбирай такие пары, пока можешь.`, `Пар получится больше 512. Посмотри на квадратные корни из произведений пар.`],
        sol: `Простых чисел, не больших 23, девять: 2, 3, 5, 7, 11, 13, 17, 19, 23. Сопоставим числу набор чётностей девяти показателей — всего 2<sup>9</sup> = 512 наборов. Если чисел хотя бы 513, два имеют одинаковый набор, и их произведение — точный квадрат. Будем выбирать такие пары и убирать их из M, пока остаётся хотя бы 513 чисел: начав с 1985, получим не меньше 737 непересекающихся пар (после 736 пар остаётся 513 чисел, и можно взять ещё одну). Произведение пары i равно c<sub>i</sub><sup>2</sup>, где c<sub>i</sub> тоже не имеет простых делителей больше 23. Так как 737 > 512, у каких-то c<sub>i</sub> и c<sub>j</sub> одинаковые наборы чётностей, и c<sub>i</sub>c<sub>j</sub> = d<sup>2</sup>. Тогда произведение четырёх чисел из этих двух пар равно c<sub>i</sub><sup>2</sup>c<sub>j</sub><sup>2</sup> = d<sup>4</sup>.`,
        rubric: [[2, `Введены наборы чётностей показателей, их 512`], [2, `Выбрано не меньше 513 непересекающихся пар с квадратным произведением`], [2, `Повторный принцип Дирихле для корней из произведений`], [1, `Вывод: произведение четырёх чисел — четвёртая степень`]] }
    ]
  });
})();

